// Replace these values with your completed crawl and required pages.
// Review the crawler's failed-request count yourself; this is not inferred.
return [{ json: {
  sourceRunId: 'REPLACE_WITH_FINISHED_CRAWL_RUN_ID',
  namespace: 'client-help-center',
  expectedUrls: ['https://example.com/help/returns'],
  upstreamFailedRequests: null,
  previousManifest: null
} }];

const c = $input.first().json;
if (typeof c.sourceRunId !== 'string' || !/^[A-Za-z0-9]{17}$/.test(c.sourceRunId)) throw new Error('Set sourceRunId to the finished crawler run ID.');
if (typeof c.namespace !== 'string' || !/^[A-Za-z0-9_-]{1,80}$/.test(c.namespace)) throw new Error('Set a stable namespace.');
if (!Number.isInteger(c.upstreamFailedRequests) || c.upstreamFailedRequests < 0) throw new Error('Review the source failed-request count and set upstreamFailedRequests explicitly.');
if (c.upstreamFailedRequests !== 0) throw new Error('Source has failed requests. Keep the current knowledge base.');
if (!Array.isArray(c.expectedUrls) || c.expectedUrls.length > 1000 || c.expectedUrls.some(u => typeof u !== 'string' || !/^https?:\/\/[^\s]+$/.test(u))) throw new Error('Provide valid expectedUrls.');
if (!c.expectedUrls.length && !c.previousManifest) throw new Error('Supply required URLs or a previously committed manifest to detect missing pages.');
return [{json:c}];

const run = $input.first().json.data;
const c = $('Validate configuration').first().json;
if (!run || run.id !== c.sourceRunId || run.status !== 'SUCCEEDED' || !run.finishedAt || !/^[A-Za-z0-9]{17}$/.test(run.defaultDatasetId ?? '')) throw new Error('Source is not a completed successful crawl. Keep the current knowledge base.');
const auditInput = {mode:'dataset', namespace:c.namespace, datasetId:run.defaultDatasetId, sourceFinished:true, upstreamFailedRequests:c.upstreamFailedRequests, expectedUrls:c.expectedUrls};
if (c.previousManifest) auditInput.previousManifest = c.previousManifest;
return [{json:{auditInput,sourceRunId:run.id}}];

const run = $input.first().json.data;
if (!run || run.status !== 'SUCCEEDED' || !run.finishedAt || !/^[A-Za-z0-9]{17}$/.test(run.defaultKeyValueStoreId ?? '') || !/^[A-Za-z0-9]{17}$/.test(run.id ?? '')) throw new Error('Audit has not finished successfully. Keep the current knowledge base. Inspect the existing run before retrying: ' + (run?.id ?? 'unknown'));
return [{json:{auditRunId:run.id,storeId:run.defaultKeyValueStoreId}}];

const report = $input.first().json;
const source = $('Require completed source').first().json;
const audit = $('Require successful audit').first().json;
if (report.schemaVersion !== 1 || report.demo !== false || report.namespace !== source.auditInput.namespace || report.source?.type !== 'dataset' || report.source?.id !== source.auditInput.datasetId || typeof report.gatePassed !== 'boolean' || !['PASS','BLOCK'].includes(report.status) || report.gatePassed !== (report.status === 'PASS') || report.deletionAuthorized !== false || report.manifest?.acceptable !== report.gatePassed || !Number.isInteger(report.summary?.errorCount) || report.summary.errorCount < 0 || report.gatePassed !== (report.summary.errorCount === 0)) throw new Error('Unexpected audit report. Keep the current knowledge base.');
return [{json:{gatePassed:report.gatePassed,auditRunId:audit.auditRunId,sourceRunId:source.sourceRunId,sourceDatasetId:source.auditInput.datasetId,report,reportUrl:'https://console.apify.com/actors/runs/' + audit.auditRunId + '#output'}}];
